'use strict';
function courseAnswerPad(stage,reference){if(reference)return reference;if(!stage)return null;let pad=stage.querySelector('.tp-answer-pad');if(!pad){pad=document.createElement('div');pad.className='tp-answer-pad';pad.textContent='Drag your choice here, or tap its picture.';stage.prepend(pad);}return pad;}
function courseSlotDrop(state,id,index,render){const old=state.selected.indexOf(id);if(old>=0){[state.selected[old],state.selected[index]]=[state.selected[index],state.selected[old]];}else if(index<=state.selected.length)state.selected[index]=id;render('You moved a picture. Check the plan when you are ready.');}
function courseMovableSlot(el,index,state,targets,render,bind){if(state.selected[index]===undefined)return;bind(el,{targets:()=>targets().filter((_,i)=>i<state.selected.length),drop:target=>{const all=targets(),to=all.indexOf(target);if(to>=0&&to!==index){[state.selected[index],state.selected[to]]=[state.selected[to],state.selected[index]];render('The pictures swapped.');}}});if(!el.matches('button')){el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','Change selected picture '+(index+1));el.onclick=()=>{state.selected.splice(index,1);render('Choose another picture for the open space.');};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};}}
TouchPlay.register(bind=>{const q=sel=>app.querySelector(sel),qa=sel=>[...app.querySelectorAll(sel)],simple=(el,target,drop)=>bind(el,{targets:typeof target==='function'?target:()=>[target],drop});
 if(q('[data-choice]')){const target=q('.target');qa('[data-choice]').forEach(el=>simple(el,target,()=>el.click()));}
 if(q('[data-home]'))for(const src of qa('.target,.active-token'))simple(src,()=>qa('[data-home]'),target=>target.click());
 if(q('[data-pair]'))qa('[data-pair]:not(:disabled)').forEach(el=>simple(el,()=>qa('[data-pair]:not(:disabled)').filter(other=>other!==el),target=>{current.selected=+el.dataset.pair;pairPicture(+target.dataset.pair);}));
 if(q('[data-color]'))qa('[data-color],[data-dots]').forEach(el=>simple(el,q('.built-picture'),()=>el.click()));
 if(q('[data-learning-choice]')&&!learningState.answered){const s=learningState;if(isSequenceTask()){const slots=()=>qa('[data-slot]');qa('[data-learning-choice]:not(:disabled)').forEach(el=>bind(el,{targets:()=>slots().filter((_,i)=>i<=s.selected.length),drop:target=>courseSlotDrop(s,s.options[+el.dataset.learningChoice].id,+target.dataset.slot,renderLearningTask)}));slots().forEach((el,i)=>{if(s.selected[i]!==undefined)bind(el,{targets:()=>[...slots().filter((_,j)=>j<s.selected.length),q('.learning-options')],drop:target=>{if(target.matches('.learning-options'))s.selected.splice(i,1);else{const j=+target.dataset.slot;[s.selected[i],s.selected[j]]=[s.selected[j],s.selected[i]];}s.swapping=null;renderLearningTask('You moved an event. Check your story when ready.');}});});}else{const stage=q('.learning-stage'),target=courseAnswerPad(stage,q('.reference-strip'));qa('[data-learning-choice]').forEach(el=>simple(el,target,()=>el.click()));}}
 if(q('[data-adult-choice]')&&!adultState.answered){const s=adultState;if(s.mode==='order'){const slots=()=>qa('.adult-order-slots .story-frame');qa('[data-adult-choice]:not(:disabled)').forEach(el=>bind(el,{targets:()=>slots().filter((_,i)=>i<=s.selected.length),drop:target=>courseSlotDrop(s,s.options[+el.dataset.adultChoice].id,slots().indexOf(target),renderAdultTask)}));slots().forEach((el,i)=>courseMovableSlot(el,i,s,slots,renderAdultTask,bind));}else{const target=courseAnswerPad(q('.adult-stage'),q('.adult-reference'));qa('[data-adult-choice]').forEach(el=>simple(el,target,()=>el.click()));}}
 if(q('#adultAdd')){simple(q('#adultAdd'),q('.sound-counters'),()=>q('#adultAdd')?.click());qa('.sound-counter.filled').forEach(el=>simple(el,q('#adultRemove'),()=>q('#adultRemove')?.click()));}
 if(q('.sen-play')&&senState?.task&&!senState.done){const s=senState,t=s.task;if(t.mode==='order'){const slots=()=>qa('.sen-story-slots .story-frame');qa('[data-sen-choice]:not(:disabled)').forEach(el=>bind(el,{targets:()=>slots().filter((_,i)=>i<=s.selected.length),drop:target=>courseSlotDrop(s,t.options[+el.dataset.senChoice].id,slots().indexOf(target),senRender)}));slots().forEach((el,i)=>courseMovableSlot(el,i,s,slots,senRender,bind));}else if(t.mode==='compose'){qa('[data-compose]').forEach(el=>simple(el,()=>[qa('.sen-story-slots .story-frame')[+el.dataset.compose.split(':')[0]]],()=>el.click()));}else if(t.mode==='place'){simple(q('.sen-reference .story-frame'),()=>qa('[data-sen-choice]'),target=>{const index=target.dataset.senChoice;if(!s.reveal)q('#senPick')?.click();q(`[data-sen-choice="${index}"]`)?.click();});}else if(t.options?.length){const target=courseAnswerPad(q('.sen-stage'),q('#senChoiceHome')||q('.sen-reference'));qa('[data-sen-choice]').forEach(el=>simple(el,target,()=>el.click()));}if(t.mode==='counter'){simple(q('#senAdd'),q('.sen-pebbles'),()=>q('#senAdd')?.click());qa('.sen-pebbles .sound-counter.filled').forEach(el=>simple(el,q('#senRemove'),()=>q('#senRemove')?.click()));}}
 if(q('.focus-play')&&focusState?.task&&!focusState.done&&!focusState.paused){const s=focusState,t=s.task;if(['collect','checklist'].includes(t.mode)&&!q('.focus-packed')){const packed=document.createElement('div');packed.className='focus-packed';packed.setAttribute('aria-label','Packed items');packed.innerHTML=`<div class="focus-packed-basket">${pictureIcon('basket')}</div><div><small>Our packed things</small><div class="focus-packed-items">${s.selected.length?s.selected.map(id=>`<span>${focusPicture(t.options.find(o=>o.id===id).picture)}</span>`).join(''):'<span class="focus-packed-empty">Drag here, or tap a picture.</span>'}</div></div>`;q('.focus-options').before(packed);}if(t.mode==='order'){const slots=()=>qa('.focus-chosen .story-frame');qa('[data-focus-choice]:not(:disabled)').forEach(el=>bind(el,{targets:()=>slots().filter((_,i)=>i<=s.selected.length),drop:target=>courseSlotDrop(s,el.dataset.focusChoice,slots().indexOf(target),focusRender)}));slots().forEach((el,i)=>courseMovableSlot(el,i,s,slots,focusRender,bind));}else if(t.mode==='plan'){qa('[data-focus-plan]').forEach(el=>{if(!el.dataset.focusPlan.endsWith(':2'))simple(el,()=>[el.closest('fieldset')],()=>el.click());});}else if(t.options?.length){const target=courseAnswerPad(q('.game-stage'),q('.focus-packed')||q('.focus-goal'));qa('[data-focus-choice]:not(:disabled)').forEach(el=>simple(el,target,()=>el.click()));}}
 if(q('.calm-play')&&calmState){if(q('[data-calm-choice]'))qa('[data-calm-choice]').forEach(el=>simple(el,q('.calm-model'),()=>el.click()));if(q('[data-calm-open]')){const pad=courseAnswerPad(q('.game-stage'));qa('[data-calm-open]').forEach(el=>simple(el,pad,()=>el.click()));}qa('[data-calm-routine]').forEach(el=>{if(!el.dataset.calmRoutine.endsWith(':2'))simple(el,el.closest('fieldset'),()=>el.click());});}
});
